component.css:
.msv {--ink: #2a3440;--dim: #6b7480;--panel: #f8f0de;--acc: #2d5680;--gold: #b98a2e;position: relative;width: 100%;aspect-ratio: 1672 / 941;container-type: size;overflow: hidden;border-radius: 10px;background: #0d1420;font-family: "PingFang SC","Microsoft YaHei",sans-serif;user-select: none;-webkit-user-select: none;}
.msv *, .msv *::before, .msv *::after { box-sizing: border-box; }
.msv button { font-family: inherit; border: 0; background: none; padding: 0; margin: 0; cursor: pointer; color: inherit; text-align: left; }
.msv button:focus { outline: none; }
.msv button:focus-visible { outline: 2px solid #4e86b4; outline-offset: 1px; }
.msv-bg { position: absolute; inset: 0; background: url("https://origin.picgo.net/2026/10/21/1000086358709d3ef19b5e4494.png") center / 100% 100% no-repeat; pointer-events: none; }
.msv-slots, .msv-pager { position: absolute; inset: 0; }
.msv-slot {position: absolute; width: 22.7%; height: 22.7%;border-radius: 6px;overflow: hidden;transition: box-shadow .15s;}
@media (hover: hover) {.msv-slot:hover { box-shadow: inset 0 0 0 2px #2d56809c; }}
.msv-slot.is-arm { box-shadow: inset 0 0 0 3px #b98a2ecc; animation: msvArm 1s ease-in-out infinite; }
@keyframes msvArm { 50% { box-shadow: inset 0 0 0 3px #b98a2e66; } }
.msv-slot__in {position: absolute; inset: 7% 8% 6%;display: flex; flex-direction: column; justify-content: space-between;color: var(--ink);}
.msv-slot__top { display: flex; align-items: baseline; gap: 2%; font-size: 1.55cqh; color: var(--dim); }
.msv-slot__top b { font-size: 1.9cqh; color: var(--acc); letter-spacing: .05em; }
.msv-slot__loc {font-size: 2.35cqh; font-weight: 700; color: var(--ink);letter-spacing: .04em;overflow: hidden; white-space: nowrap; text-overflow: ellipsis;}
.msv-slot__sub { display: flex; align-items: baseline; gap: 5%; font-size: 1.5cqh; color: var(--dim); }
.msv-slot__sub b { color: #8a5a28; font-weight: 700; }
.msv-slot__scene {font-size: 1.45cqh; line-height: 1.4; color: #4d5661;display: -webkit-box; -webkit-box-orient: vertical; -webkit-line-clamp: 2; overflow: hidden;}
.msv-slot__hint {position: absolute; inset: 0;display: flex; align-items: center; justify-content: center;font-size: 1.7cqh; letter-spacing: .2em;color: #2a344066;pointer-events: none;}
.msv-slot.is-empty:hover .msv-slot__hint { color: #2d5680; }
.msv-pager__btn {position: absolute; top: 79%; height: 10%; display: flex; align-items: center; justify-content: center;font-size: 2.6cqh; color: var(--ink); border-radius: 4px;}
.msv-pager__btn--num { width: 7%; }
.msv-pager__btn--num.is-cur { color: var(--acc); font-weight: 800; text-decoration: underline; text-underline-offset: .5cqh; }
@media (hover: hover) {.msv-pager__btn:hover { background: #2d568024; }}
#msvBack { position: absolute; left: 1.5%; top: 91.8%; width: 11.5%; height: 5.5%; border-radius: 6px; }
@media (hover: hover) {#msvBack:hover { background: #2d56803d; box-shadow: inset 0 0 0 2px #4e86b480; }}

